local function request_lock()
  return {
    status = "Lock requested",
    actions = { { type = "lockDevice" } }
  }
end

function on_event(event)
  if event.type == "manual" then
    return request_lock()
  end
  if event.type == "deviceAdminState" and event.payload.active then
    return request_lock()
  end
  return { status = "Waiting for Device Administration" }
end

local function two_digits(value)
  if value < 10 then return "0" .. tostring(value) end
  return tostring(value)
end

function on_event(event)
  local clock = two_digits(event.time.hour24) .. ":" .. two_digits(event.time.minute)
  return {
    status = "Notification requested for " .. clock,
    actions = {
      { type = "postNotification", title = "Dikciz clock", text = "Current time: " .. clock }
    }
  }
end

local function unavailable_status()
  return { status = "Enable cross-app automation in Android Settings" }
end

function on_event(event)
  if event.type == "manual" then
    if not context.androidAccess.accessibility then
      return unavailable_status()
    end
    return {
      status = "Opening Android Settings",
      actions = { { type = "launchApp", component = "com.android.settings/.Settings" } }
    }
  end

  if event.type ~= "accessibilityWindow" or event.payload.packageName ~= "com.android.settings" then
    return { status = "Waiting for Android Settings" }
  end

  local accessibility = context.accessibility
  if accessibility == nil then
    return { status = "Settings snapshot unavailable" }
  end

  for _, node in ipairs(accessibility.nodes) do
    if node.text == "Network & internet" and node.visibleToUser then
      local parent = string.match(node.nodeId, "^(.*)%.%d+$")
      if parent ~= nil then
        return {
          status = "Opening Network & internet",
          actions = { {
            type = "accessibilityAction",
            snapshotId = accessibility.snapshotId,
            nodeId = parent,
            action = "click"
          } }
        }
      end
    end
  end

  return { status = "Network & internet is not visible" }
end
